    int n; long long s = 0; vector<long long> P;
    RotSum(const vector<long long>& a): n(a.size()), P(2 * a.size() + 1, 0){
        for (int i = 0; i < 2 * n; i++) P[i+1] = P[i] + a[i % n];
    }
    void left(long long k){ s = (s + k % n) % n; }
    void right(long long k){ s = ((s - k % n) % n + n) % n; }
    long long sum(int l, int r){ return P[s + r + 1] - P[s + l]; }
};

int main(){
