void nextPerm(vector<int>& a){
    int n = a.size(), i = n - 2;
    while (i >= 0 && a[i] >= a[i+1]) i--;
    if (i >= 0){
        int j = n - 1;
        while (a[j] <= a[i]) j--;
        swap(a[i], a[j]);
    }
    reverse(a.begin() + i + 1, a.end());
}

long long subarraySumK(const vector<long long>& a, long long k){
    unordered_map<long long,long long> cnt; cnt[0] = 1;
    long long p = 0, ans = 0;
    for (long long x : a){
        p += x;
        auto it = cnt.find(p - k);
        if (it != cnt.end()) ans += it->second;
        cnt[p]++;
    }
    return ans;
}

vector<array<int,3>> threeSum(vector<int> a, long long T = 0){
    sort(a.begin(), a.end()); vector<array<int,3>> r; int n = a.size();
    for (int i = 0; i + 2 < n; i++){
        if (i && a[i] == a[i-1]) continue;
        int l = i + 1, h = n - 1;
        while (l < h){
            long long s = (long long)a[i] + a[l] + a[h];
            if (s == T){
                r.push_back({a[i], a[l], a[h]});
                while (l < h && a[l] == a[l+1]) l++;
                while (l < h && a[h] == a[h-1]) h--;
                l++; h--;
            } else if (s < T) l++; else h--;
        }
    }
    return r;
}

long long standingKm(long long cap, vector<array<long long,3>> trips){
    map<long long,long long> ev;
    for (auto& t : trips){ ev[t[1]] += t[0]; ev[t[2]] -= t[0]; }
    long long load = 0, ans = 0, prev = 0; bool first = true;
    for (auto& [pos, d] : ev){
        if (!first && load > cap) ans += (load - cap) * (pos - prev);
        load += d; prev = pos; first = false;
    }
    return ans;
}

int maxIndexDiff(const vector<int>& a){
    int n = a.size(); if (n < 2) return -1;
    vector<int> L(n), R(n);
    L[0] = a[0]; for (int i = 1; i < n; i++) L[i] = min(L[i-1], a[i]);
    R[n-1] = a[n-1]; for (int j = n - 2; j >= 0; j--) R[j] = max(R[j+1], a[j]);
    int i = 0, j = 0, best = -1;
    while (i < n && j < n){
        if (L[i] < R[j]){ if (j > i) best = max(best, j - i); j++; }
        else i++;
    }
    return best;
}

long long countEqualSecondDiff(const vector<long long>& a){
    int n = a.size(); if (n < 4) return 0;
    long long ans = 0, run = 0, prev = 0;
    for (int i = 0; i + 2 < n; i++){
        long long d = a[i+2] - 2 * a[i+1] + a[i];
        run = (i > 0 && d == prev) ? run + 1 : 1;
        ans += run - 1;   // adds m(m-1)/2 over a run of length m
        prev = d;
    }
    return ans;
}

long long delayedProfit(const vector<long long>& p){
    int n = p.size(); vector<long long> suf(n + 1, LLONG_MIN);
    for (int j = n - 1; j >= 0; j--) suf[j] = max(suf[j+1], p[j]);
    long long best = 0;
    for (int i = 0; i < n; i++){
        long long e = i + p[i] % 10 + 1;
        if (e < n) best = max(best, suf[e] - p[i]);
    }
    return best;
}

vector<long long> xSeries(const vector<long long>& a){
    map<long long,int> f; for (long long x : a) f[x]++;
    vector<long long> u; for (auto& [v, c] : f) u.push_back(v);
    vector<long long> best;
    for (long long x : u) for (long long y : u){
        if (x == y && f[x] < 2) continue;
        map<long long,int> used; used[x]++; used[y]++;
        vector<long long> s = {x, y};
        while (true){
            long long z = s[s.size()-1] + s[s.size()-2];
            auto it = f.find(z);
            if (it == f.end() || used[z] >= it->second) break;
            used[z]++; s.push_back(z);
        }
        if (s.size() > best.size()) best = s;
    }
    if (best.size() < 3) return {};   // print -1
    return best;
}

