int firstMissingPositive(vector<int> a){
    int n = a.size();
    for (int i = 0; i < n; i++)
        while (a[i] >= 1 && a[i] <= n && a[a[i]-1] != a[i]) swap(a[i], a[a[i]-1]);
    for (int i = 0; i < n; i++) if (a[i] != i + 1) return i + 1;
    return n + 1;
}

int maxDivGap(const vector<int>& a){
    int n = a.size(), mx = *max_element(a.begin(), a.end()), best = -1;
    if (mx <= 10000000){
        vector<int> pos(mx + 1, -1);
        for (int i = 0; i < n; i++) if (a[i] > 0) pos[a[i]] = i;
        for (int i = 0; i < n; i++){
            int v = a[i]; if (v <= 1) continue;
            for (long long m = 2LL * v; m <= mx; m += v)
                if (pos[m] > i) best = max(best, pos[m] - i);
        }
    } else {
        for (int i = 0; i < n; i++) if (a[i] > 1)
            for (int j = n - 1; j > i; j--) if (a[j] % a[i] == 0){ best = max(best, j - i); break; }
    }
    return best;
}

