long long minAdjSwaps(const vector<int>& A, const vector<int>& B){
    int n = A.size(); map<int, deque<int>> where;
    for (int i = 0; i < n; i++) where[B[i]].push_back(i);
    vector<int> P(n), bit(n + 1, 0);
    for (int i = 0; i < n; i++){
        auto& q = where[A[i]]; if (q.empty()) return -1;
        P[i] = q.front(); q.pop_front();
    }
    long long inv = 0;
    for (int i = 0; i < n; i++){
        int c = 0; for (int x = P[i] + 1; x > 0; x -= x & -x) c += bit[x];  // seen with P <= P[i]
        inv += i - c;
        for (int x = P[i] + 1; x <= n; x += x & -x) bit[x]++;
    }
    return inv;
}

long long maxSumKSwaps(const vector<long long>& a, int K){
    int n = a.size(); long long best = LLONG_MIN;
    for (int l = 0; l < n; l++) for (int r = l; r < n; r++){
        vector<long long> in(a.begin() + l, a.begin() + r + 1), out;
        for (int i = 0; i < n; i++) if (i < l || i > r) out.push_back(a[i]);
        sort(in.begin(), in.end()); sort(out.rbegin(), out.rend());
        long long s = accumulate(in.begin(), in.end(), 0LL);
        for (int t = 0; t < K && t < (int)in.size() && t < (int)out.size() && out[t] > in[t]; t++)
            s += out[t] - in[t];
        best = max(best, s);
    }
    return best;
}
